import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`responder: acknowledge and resolve incidents I'm working on`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a responder acknowledges an incident, its status changes to 'acknowledged' for everyone within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0: create an incident
      await pageA.getByTestId('action-create_incident').click();
      await pageA.getByTestId('field-title').fill('Acknowledge test incident');
      await pageA.getByTestId('field-description').fill('Testing acknowledgement propagation');
      await pageA.getByTestId('field-severity').fill('high');
      await pageA.getByTestId('action-create_incident').click();

      // Node 0: navigate to the incident and acknowledge it
      await pageA.getByTestId('item-incident').filter({ hasText: 'Acknowledge test incident' }).click();
      await pageA.getByTestId('action-acknowledge_incident').click();

      // Node 1: the incident should show 'acknowledged' status within 5s
      const incidentOnB = pageB.getByTestId('item-incident').filter({ hasText: 'Acknowledge test incident' });
      await expect(incidentOnB).toBeVisible({ timeout: 5_000 });
      await expect(incidentOnB).toContainText('acknowledged');
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`after a responder resolves an incident, its status changes to 'resolved' and it moves out of the active list`, async ({ page }) => {
    // Create an incident
    await page.getByTestId('action-create_incident').click();
    await page.getByTestId('field-title').fill('Resolve test incident');
    await page.getByTestId('field-description').fill('Testing resolution flow');
    await page.getByTestId('field-severity').fill('medium');
    await page.getByTestId('action-create_incident').click();

    // Confirm it appears in the active list
    const incidentItem = page.getByTestId('item-incident').filter({ hasText: 'Resolve test incident' });
    await expect(incidentItem).toBeVisible({ timeout: 5_000 });

    // Navigate to the incident and resolve it
    await incidentItem.click();
    await page.getByTestId('action-resolve_incident').click();

    // Return to the dashboard — the incident must no longer appear in the active list
    await page.goBack();
    await expect(
      page.getByTestId('item-incident').filter({ hasText: 'Resolve test incident' })
    ).toBeHidden({ timeout: 5_000 });
  });
});
